    -- 场景
    local sceneRoot = self.UiSceneInfo.Transform
    local constellationList = sceneRoot:Find("GroupBase/ConstellationList")
    if constellationList then
        self.SceneConstellationGoDic = {}
        local CONSTELLATION_PREFIX = "Constellation"
        local prefixCount = #CONSTELLATION_PREFIX
        local constellationConfigs = self._Control:GetLifeTreeConstellationConfigs()
        
        local childCount = constellationList.childCount
        for i = 0, childCount - 1 do
            local child = constellationList:GetChild(i)
            if child then
                local name = child.gameObject.name
                if stringSub(name, 1, prefixCount) == CONSTELLATION_PREFIX then
                    -- 去掉前缀，提取数字部分
                    local numStr = stringSub(name, prefixCount + 1)
                    local id = tonumber(numStr)
                    local isExit = constellationConfigs[id] ~= nil
                    child.gameObject:SetActive(isExit)
                    if isExit then
                        self.SceneConstellationGoDic[id] = child
                    end
                end
            end
        end
    end
end

