function XUiLifeTreeMain:RefreshBtnTask()
    local config = self._Control:GetLifeTreeClientConfigConfigById("TaskPreviewRewardId")
    local rewardId = tonumber(config.Values[1])
    local rewardItems = XRewardManager.GetRewardList(rewardId)
    XTool.UpdateDynamicGridCommon(self._Grid256NewArray, rewardItems, self.Grid256New, self)

    local taskIds = self._Control:GetTaskIds()
    local finishCnt = 0
    local allCnt = #taskIds
    for _, taskId in ipairs(taskIds) do
        local isFinish = XDataCenter.TaskManager.IsTaskFinished(taskId)
        if isFinish then
            finishCnt = finishCnt + 1
        end
    end
    local isAllFinish = finishCnt >= allCnt
    self.ImgLingqu.gameObject:SetActiveEx(isAllFinish)
    self.TxtTaskProgress.text = string.format("<color=#7db5ff>%s</color>/%s", finishCnt, allCnt)
    
    -- 蓝点
    local isRed = XMVCA.XLifeTree:IsRedTask()
    self.BtnTask:ShowReddot(isRed)
end

