    if animGo then
        animGo.gameObject:SetActiveEx(true)
        local playType = isBack and CSDirctorPlayType.Back or CSDirctorPlayType.Forward
        local playTypeInt = CS.System.Convert.ToInt32(playType)
        local speed = 1
        animGo.gameObject:PlayTimelineAnimation(playTypeInt, speed, cb)
        return
    end
end

