-- 检测处理镜头移动衰减
function XUiLifeTreeMain:CheckCameraMoveFade()
    if self.IsPlayCameraAnim then return end  -- 播生命树、意识海的摄像机切换动画时，不需要进行镜头移动衰减
    if not self.LastDragTime then return end
    if self.CurXInput == 0 and self.CurYInput == 0 then return end

    local curTime = CS.UnityEngine.Time.realtimeSinceStartup
    local fadeProgress = (curTime - self.LastDragTime) / CAMERA_FADE_TIME
    fadeProgress = EaseExpoOut(fadeProgress)
    if self.CurXInput ~= 0 then
        local xInput = Lerp(self.LastDragXInput, 0, fadeProgress)
        self:SetCameraXInput(xInput)
    end

    if self.CurYInput ~= 0 then
        local yInput = Lerp(self.LastDragYInput, 0, fadeProgress)
        self:SetCameraYInput(yInput)
    end
    self.IsCameraPosValueChange = true
end

-- 设置摄像机的X轴和Y轴的值，并通过动画逐渐切换到目标值
function XUiLifeTreeMain:SetCameraValueWithAnim(aimXValue, aimYValue)
    local curXValue = self.CamFarMain:GetXValue()
    local curYValue = self.CamFarMain:GetYValue()
    local startTime = CS.UnityEngine.Time.realtimeSinceStartup
    self:RemoveSetCameraValueTimer()
    self.IsPlayCameraAnim = true
    self.SetCameraValueTimer = XScheduleManager.ScheduleForever(function()
        local progress = (CS.UnityEngine.Time.realtimeSinceStartup - startTime) / CHANGE_CAMERA_VALUE_TIME
        progress = EaseQuadOut(progress)
        local xValue = Lerp(curXValue, aimXValue, progress)
        local yValue = Lerp(curYValue, aimYValue, progress)
        self:SetCameraXValue(xValue)
        self:SetCameraYValue(yValue)
        self.IsCameraPosValueChange = true
        if progress >= 1 then
            self:RemoveSetCameraValueTimer()
        end
    end, 0)
end

function XUiLifeTreeMain:RemoveSetCameraValueTimer()
    if self.SetCameraValueTimer then
        XScheduleManager.UnSchedule(self.SetCameraValueTimer)
        self.SetCameraValueTimer = nil
    end
    self.IsPlayCameraAnim = false
end

-- 摄像机位置值发生变化
function XUiLifeTreeMain:OnCameraPosValueChange()
    self:CheckSwitchState()
    self:CheckUpdateUiPointPos()
end

-- 检测切换状态
function XUiLifeTreeMain:CheckSwitchState()
    local yValue = self.CamFarMain:GetYValue()
    local isSea = yValue > CAMERA_Y_VALUE_SWITCH
    local isLifeTree = not isSea
    if self.State ~= STATE.SEA and isSea then
        self:OnSwitchSea()
    elseif self.State ~= STATE.LIFE_TREE and isLifeTree then
        self:OnSwitchLifeTree()
    end
end

-- 检测更新Ui点位位置
function XUiLifeTreeMain:CheckUpdateUiPointPos()
    for _, gridCard in pairs(self.GridCards) do
        gridCard:UpdatePosition()
    end
end

