--region PanelCard
-- 初始化卡牌节点
function XUiLifeTreeMain:InitCards()
    self.GridDivineCard.gameObject:SetActiveEx(false)
    self.GridRegularCard.gameObject:SetActiveEx(false)

    -- 卡牌跟随的3D点位
    ---@type (XUiLifeTreeMainGridDivineCard|XUiLifeTreeMainGridRegularCard)[]
    self.GridCards = {}
    local sceneRoot = self.UiSceneInfo.Transform
    local sceneUi = sceneRoot:Find("GroupBase/Ui")
    local constellationConfigs = self._Control:GetLifeTreeConstellationConfigs()
    for constellationId, constellationConfig in pairs(constellationConfigs) do
        local catalogIds = constellationConfig.CharacterCatalogIds
        for _, catalogId in ipairs(catalogIds) do
            local catalogConfig = self._Control:GetLifeTreeCharacterCatalogConfigById(catalogId)
            local follow3DGo = sceneUi:Find(catalogConfig.SceneFollowPoint)
            if not follow3DGo then
                XLog.Error(string.format("UiMain3dLifeTree场景缺少节点GroupBase/Ui/%s", catalogConfig.SceneFollowPoint))
                goto CONTINUE
            end
            if catalogConfig.CardType == XMVCA.XLifeTree.EnumConst.CARD_TYPE.DIVINE then
                local go = CSInstantiate(self.GridDivineCard, self.PanelCard)
                self.GridCards[catalogId] = XUiLifeTreeMainGridDivineCard.New(go, self, constellationId, catalogId, follow3DGo)
            else
                local go = CSInstantiate(self.GridRegularCard, self.PanelCard)
                go.transform:SetAsFirstSibling()
                self.GridCards[catalogId] = XUiLifeTreeMainGridRegularCard.New(go, self, constellationId, catalogId, follow3DGo)
            end
            self.GridCards[catalogId]:Open()
            :: CONTINUE ::
        end
    end
end

-- 刷新场景星座列表状态
function XUiLifeTreeMain:RefreshSceneConstellations()
    for constellationId, go in pairs(self.SceneConstellationGoDic) do
        --local catalogId = self._Control:GetConstellationDivineCharacterCatalogId(constellationId) -- 神卡CatalogId
        --local isUnlock = self._Control:IsCharacterUnlock(catalogId)
        local isRed = XMVCA.XLifeTree:IsRedConstellation(constellationId)
        --go:Find("Lock").gameObject:SetActiveEx(not isUnlock)
        go:Find("Unlock").gameObject:SetActiveEx(not isRed)
        go:Find("EffectRed").gameObject:SetActiveEx(isRed)
    end
end

--endregion

return XUiLifeTreeMain
